window.ScripturaLexicons.BDAG_PART_0313 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-01\" data-source=\"BDAG\" data-search=\"πωλέω verbo vender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πωλέω</td><td>verbo</td><td>vender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-02\" data-source=\"BDAG\" data-search=\"πῶλος, ου, ὁ substantivo masculino cria de animal, potro; cavalo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πῶλος, ου, ὁ</td><td>substantivo masculino</td><td>cria de animal, potro; cavalo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-03\" data-source=\"BDAG\" data-search=\"πῶλυψ, πος, ὁ substantivo masculino polvo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πῶλυψ, πος, ὁ</td><td>substantivo masculino</td><td>polvo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-04\" data-source=\"BDAG\" data-search=\"πώποτε advérbio alguma vez; nunca (com negação) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πώποτε</td><td>advérbio</td><td>alguma vez; nunca (com negação)</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-05\" data-source=\"BDAG\" data-search=\"πωρόω verbo endurecer, petrificar, tornar obtuso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πωρόω</td><td>verbo</td><td>endurecer, petrificar, tornar obtuso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-06\" data-source=\"BDAG\" data-search=\"πώρωσις, εως, ἡ substantivo feminino endurecimento, insensibilidade, obstinação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πώρωσις, εως, ἡ</td><td>substantivo feminino</td><td>endurecimento, insensibilidade, obstinação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-07\" data-source=\"BDAG\" data-search=\"πῶς advérbio interrogativo e exclamativo como?, de que modo?; como…! BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πῶς</td><td>advérbio interrogativo e exclamativo</td><td>como?, de que modo?; como…!</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-08\" data-source=\"BDAG\" data-search=\"πώς partícula enclítica de algum modo, talvez; para que não BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πώς</td><td>partícula enclítica</td><td>de algum modo, talvez; para que não</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-09\" data-source=\"BDAG\" data-search=\"ρ´ sinal numérico 100 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ρ´</td><td>sinal numérico</td><td>100</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-10\" data-source=\"BDAG\" data-search=\"Ῥαάβ, ἡ nome próprio feminino indeclinável Raabe BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥαάβ, ἡ</td><td>nome próprio feminino indeclinável</td><td>Raabe</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-11\" data-source=\"BDAG\" data-search=\"ῥαββί substantivo, forma de tratamento mestre, senhor, rabi BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥαββί</td><td>substantivo, forma de tratamento</td><td>mestre, senhor, rabi</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-12\" data-source=\"BDAG\" data-search=\"ῥαββουνί substantivo, forma de tratamento meu senhor, meu mestre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥαββουνί</td><td>substantivo, forma de tratamento</td><td>meu senhor, meu mestre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-13\" data-source=\"BDAG\" data-search=\"ῥαβδίζω verbo bater com vara, espancar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥαβδίζω</td><td>verbo</td><td>bater com vara, espancar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-14\" data-source=\"BDAG\" data-search=\"ῥαβδίον, ου, τό substantivo neutro graveto, pequena vara BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥαβδίον, ου, τό</td><td>substantivo neutro</td><td>graveto, pequena vara</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-15\" data-source=\"BDAG\" data-search=\"ῥάβδος, ου, ἡ substantivo feminino vara, bastão, cajado, cetro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥάβδος, ου, ἡ</td><td>substantivo feminino</td><td>vara, bastão, cajado, cetro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-16\" data-source=\"BDAG\" data-search=\"ῥαβδοῦχος, ου, ὁ substantivo masculino portador de bastão, litor, oficial de polícia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥαβδοῦχος, ου, ὁ</td><td>substantivo masculino</td><td>portador de bastão, litor, oficial de polícia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-17\" data-source=\"BDAG\" data-search=\"ῥαβιθα. substantivo feminino, variante textual menina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥαβιθα.</td><td>substantivo feminino, variante textual</td><td>menina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-18\" data-source=\"BDAG\" data-search=\"Ῥαγαύ nome próprio masculino indeclinável Reú BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥαγαύ</td><td>nome próprio masculino indeclinável</td><td>Reú</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-19\" data-source=\"BDAG\" data-search=\"ῥᾳδιούργημα, ατος, τό substantivo neutro embuste, má ação, crime, vilania BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥᾳδιούργημα, ατος, τό</td><td>substantivo neutro</td><td>embuste, má ação, crime, vilania</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0313-20\" data-source=\"BDAG\" data-search=\"ῥᾳδιουργία, ας, ἡ substantivo feminino frivolidade, fraude, ardil, falta de escrúpulos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥᾳδιουργία, ας, ἡ</td><td>substantivo feminino</td><td>frivolidade, fraude, ardil, falta de escrúpulos</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0313-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πωλέω</span> imperf. <span class=\"greek\">ἐπώλουν</span>; 1 aor. <span class=\"greek\">ἐπώλησα</span> (Eur., Hdt.+) vender <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:44</a>; 19:21; 21:12b (sobre <span class=\"greek\">πωλεῖν</span> no <span class=\"greek\">ἱερόν</span> cf. ILegesSacr II, 88, 31); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:21</a>; 11:15b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:33</a>; 18:22 (PRyl 113, 8 <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐμαυτοῦ</span> <span class=\"greek\">πωλήσας</span>); 22:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:14</a>, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:1</a>. O objeto deve ser suprido 4:34, 37.—Pass. ser oferecido à venda, ser vendido (Artem. 4, 15) <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μακέλλῳ</span> <span class=\"greek\">πωλούμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:25</a> (MIsenberg, The Sale of Sacrificial Meat: ClPh 70, ’75, 271–73). Com gen. de preço (X., Mem. 1, 2, 36; PPetr II, 38(b), 2 [243 a.C.] <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔλαιον</span> <span class=\"greek\">πωλεῖσθαι</span> <span class=\"greek\">τιμῆς</span> … ; Jos., Vi. 75.—B-D-F §179, 1; Rob. 510f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:6</a>. Abs. (oposto a <span class=\"greek\">ἀγοράζειν</span>; v. <span class=\"greek\">ἀγοράζω</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:17</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">πωλοῦντες</span> os vendedores, comerciantes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:45</a>. Com <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀγοράζοντες</span> (cf. Is 24:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:12a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:15a</a>. Sobre práticas ascéticas, v. HvCampenhausen, Tradition and Life in the Church, ’68, 90–122.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πῶλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+; ins., pap., LXX; Ps-Phoc. 126; Just; Philo.)</p><p class=\"entry-text\">① animal jovem, cria (originalmente ‘potro de cavalo’: Hom. e outros; além disso, refere-se a um cavalo com idade suficiente para ser utilizado: Hipponax 41 Diehl; Anacr. 88 D.; X., De Re Equ. 1, 6 e outros; PGM 2, 95; depois qualquer ‘animal jovem’ [Aristot. e outros], aplicando-se o termo a qualquer cria da respectiva espécie, de um elefante a um gafanhoto, conforme o contexto; WBauer, The ‘Colt’ of Palm Sunday [Der Palmesel]: JBL 72, ’53, 220–29: o original alemão em WBauer, Aufsätze u. Kleine Schriften, ed. GStrecker, ’67, 109–20. Para um jumento, cf. exemplos de Geopon., 16, 21, 6; PLille e BGU 373, 7; Gen 32:15; 49:11ab) <span class=\"greek\">ὄνος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πῶλος</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτῆς</span> uma jumenta e uma cria com ela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:2</a>; cf. v. 7 e a citação no v. 5; também J 12:15: todas as três passagens ecoam Zech 9:9, cujo <span class=\"greek\">ὑποζύγιον</span> é corretamente denominado <span class=\"greek\">ὄνος</span>: cria de jumento. V. PNepper-Christensen, Das Mt-evangelium, ’58, 143–48.</p><p class=\"entry-text\">② entende-se cavalo quando <span class=\"greek\">π</span>. ocorre isoladamente, sem indicação de que seja uma cria, e pode referir-se a qualquer idade, desde o período em que é potro até o de um animal adulto de trabalho: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:2</a>, 4f, 7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:30</a>, 33ab, 35.—Just., A I, 54, 7 <span class=\"greek\">τὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πώλου</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὄνου</span> <span class=\"greek\">πῶλον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἵππου</span> <span class=\"greek\">σημαίνειν</span> <span class=\"greek\">ἐδύνατο</span>=‘o termo <span class=\"greek\">π</span>. podia significar tanto a cria de um jumento quanto a de um cavalo’; mas não há evidência de que o termo <span class=\"greek\">π</span>. tenha sido empregado, sem qualificação adicional, no sentido de ‘jumento’ ou ‘cria de jumento’; v. Bauer (1 acima), que prefere cavalo para as passagens em Mk e Lk. A maioria das traduções inglesas verte <span class=\"greek\">π</span>. por ‘colt’, e é difícil determinar que espécie de animal se pretende em suas versões de Mk e Lucas, uma vez que, semelhantemente ao uso grego, ‘colt’, sem qualificação, é ordinariamente associado a um cavalo macho jovem, embora tal restrição no uso popular não existisse em estágios anteriores da língua inglesa: v. OED s.v. ‘colt’.—HKuhn, Das Reittier Jesu usw., ZNW 50, ’59, 82–91; OMichel, Einzugsgeschichte, NTS 6, ’59/60, 81f.—V. também a literatura s.v. <span class=\"greek\">ὄνος</span>.—B. 171. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶλυψ, πος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πῶλυψ</span>, <span class=\"greek\">πος</span>, <span class=\"greek\">ὁ</span> polvo (assim Epicharmus em Athen. 7, 32f; Diphilus Siphnius [III a.C.] ibid. 8, 356e) B 10:5 v.l.; v. <span class=\"greek\">πολύπους</span>.—DELG s.v. <span class=\"greek\">πώλυπος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώποτε</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πώποτε</span> adv. (Hom.+; ins., pap., LXX; JosAs 7:8 cód. A [p. 48, 8 Bat.]; e outros; Joseph.; Philo; Ath. 21, 4; Mel., HE 4, 26, 6) relativo a um ponto indefinido no tempo, alguma vez, em qualquer ocasião Dg 8:11; MPol 8:1. Usualmente empregado com uma negação. Em regra, o verbo com que ocorre está num tempo passado, nunca, jamais <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">πώποτε</span> ninguém jamais (X., An. 1, 6, 11; Jos., C. Ap. 2, 124, Ant. 17, 310) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:18</a> (Galen II p. 66 K. <span class=\"greek\">μηδ</span>’ <span class=\"greek\">ἑωρακέναι</span> <span class=\"greek\">πώποτε</span>; PGM 5, 102 Osíris, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">εἶδε</span> <span class=\"greek\">πώποτε</span>); 8:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:12</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:37</a>.—Só raramente acerca do futuro (Batr. 178; 1 Km 25:28; PGM 4, 291) <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">διψήσει</span> <span class=\"greek\">πώποτε</span> nunca mais terá sede <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:35</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πωρόω</span> 1 aor. <span class=\"greek\">ἐπώρωσα</span>; perf. <span class=\"greek\">πεπώρωκα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40</a> v.l. Pass.: 1 aor. <span class=\"greek\">ἐπωρώθην</span>; perf. 3 pl. <span class=\"greek\">πεπώρωνται</span> Job 17:7, part. <span class=\"greek\">πεπωρωμένος</span> (v. verbete seguinte; Hippocr., Aristot. e outros; Job 17:7 [acerca dos olhos=perder o brilho]) primariamente: ‘endurecer, petrificar’; em nossa literatura somente fig., fazer alguém ter dificuldade em entender ou compreender, endurecer, petrificar, principalmente acerca dos corações <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> <span class=\"greek\">τινός</span> tornar insensível/obtuso/cego, fechar a mente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40</a> (<span class=\"greek\">ἐπήρωσεν</span> v.l.); pass. <span class=\"greek\">ἦν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">καρδία</span> <span class=\"greek\">πεπωρωμένη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:52</a>; cf. 8:17; Hm 4, 2, 1; 12, 4, 4.—Acerca de <span class=\"greek\">νοήματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a>. Acerca das próprias pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:7</a>.—Zahn sobre Ro, excurs. III p. 618–20; Windisch sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a>; KLSchmidt, D. Verstockung des Menschen durch Gott: TZ 1, ’45, 1–17.—DELG s.v. <span class=\"greek\">πῶρος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώρωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πώρωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πωρόω</span>, v. verbete anterior; Hippocr., Galen; sobre a história da palavra v. JARobinson, JTS 3, 1902, 81–93, comentário a Eph 1904, 264ff) primariamente: ‘endurecimento, embotamento’; em nossa literatura somente fig. (TestLevi 13:7 <span class=\"greek\">πώρωσις</span> <span class=\"greek\">ἁμαρτίας</span>), estado ou condição de completa falta de entendimento, obtusidade, insensibilidade, obstinação <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> (Theoph. Ant. 2, 35 [p. 188, 22]; v. <span class=\"greek\">πωρόω</span> e LCerfaux, Muséon 59, ’46, 267–79) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:18</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰσραὴλ</span> <span class=\"greek\">γέγονεν</span> a insensibilidade (=uma mente fechada) sobreveio a Israel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:25</a>.—DELG s.v. <span class=\"greek\">πῶρος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶς</h1><div class=\"entry-meta\"><span>advérbio interrogativo e exclamativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πῶς</span> (Hom.+)</p><p class=\"entry-text\">① referência interrogativa à maneira ou ao modo, de que modo? como?</p><p class=\"entry-text\">ⓐ em perguntas diretas</p><p class=\"entry-text\"><span class=\"greek\">α</span>. para determinar como algo veio a acontecer, como algo está acontecendo ou deve acontecer; com indic. como? de que modo? <span class=\"greek\">πῶς</span> <span class=\"greek\">ἔσται</span> <span class=\"greek\">τοῦτο</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:34</a>. <span class=\"greek\">πῶς</span> <span class=\"greek\">ἀναγινώσκεις</span>; 10:26; cf. a pergunta indireta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:26</a> (v. b, abaixo). <span class=\"greek\">πῶς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἠνεῴχθησάν</span> <span class=\"greek\">σου</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀφθαλμοί</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:10</a>.—3:4, 9; 9:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:10</a> (<span class=\"greek\">π</span>. <span class=\"greek\">οὖν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:35</a> (cf. 1 Ch 13:12); B 5:5 (<span class=\"greek\">π</span>. <span class=\"greek\">οὖν</span>); IEph 19:2 (<span class=\"greek\">π</span>. <span class=\"greek\">οὖν</span>); Hm 3:3 (<span class=\"greek\">π</span>. <span class=\"greek\">οὖν</span>); GJs 17:11 AcPl Ha 5, 3. Em referência ao conteúdo de um documento <span class=\"greek\">πῶς</span> <span class=\"greek\">ἀναγινώσκεις</span>; que lês?=‘Que diz o texto?’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:26</a> (v. HLjungvik, Eranos 62, ’64, 31); <span class=\"greek\">πῶς</span> <span class=\"greek\">γέγραπται</span>; Que diz o texto (acerca do Messias)? GJs 21:2 (códices). Com o sentido especial com que direito? com que provas? em que sentido? <span class=\"greek\">πῶς</span> <span class=\"greek\">λέγουσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">γραμματεῖς</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">Δαυίδ</span> <span class=\"greek\">ἐστιν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:35</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:43</a> (<span class=\"greek\">π</span>. <span class=\"greek\">οὖν</span>), 45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:41</a>, 44 (cf. Gen 39:9); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:34</a> (GrBar 10:8).—<span class=\"greek\">γέγραπται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:12</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. em perguntas que indicam surpresa como é (possível) que? não compreendo como (Manetho[?] em Jos., C. Ap. 259, uma série de perguntas que exprimem surpresa, introduzidas repetidamente por <span class=\"greek\">πῶς</span>; Lucian, Deor. Conc. 10 <span class=\"greek\">πῶς</span> <span class=\"greek\">φέρεις</span>; TestAbr B 6 p. 110, 12f [Stone p. 68]) <span class=\"greek\">πῶς</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">πεῖν</span> <span class=\"greek\">αἰτεῖς</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:9</a>.—7:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:9</a>. Com <span class=\"greek\">οὖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:19</a>; AcPl Ha 10, 9. Com uma negação (Isocr. 6, 4) <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">νοεῖτε</span>; como é possível que não compreendais? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:21</a> v.l. <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχετε</span> <span class=\"greek\">πίστιν</span>; como é que não tendes fé? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:40</a> v.l. <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">συνίετε</span>; 8:21 v.l. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:56</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. em perguntas que denotam desaprovação ou rejeição com que direito? como ousas? <span class=\"greek\">πῶς</span> <span class=\"greek\">ἐρεῖς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀδελφῷ</span> <span class=\"greek\">σου</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:4</a> (<span class=\"greek\">πῶς</span> <span class=\"greek\">ἐρεῖς</span> como Jer 2:23). <span class=\"greek\">πῶς</span> <span class=\"greek\">εἰσῆλθες</span> <span class=\"greek\">ὧδε</span>; como é que tens a audácia de entrar aqui? 22:12. <span class=\"greek\">πῶς</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">λέγεις</span>; como podes dizer? (cf. Job 33:12; TestAbr B 10 p. 115, 4 [Stone p. 78, 4]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:9</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:42</a>; que quer ele dizer ao afirmar? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:42</a>; 8:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:14</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. em perguntas retóricas que põem em questão uma suposição ou a rejeitam inteiramente como (poderia ou deveria)?=de modo algum, é impossível que (Job 25:4; Ar. 3, 2 e outros; Just., D. 51, 2 e outros; Tat., 4, 2; Ath. 16, 4; 19, 2) <span class=\"greek\">πῶς</span> (<span class=\"greek\">οὖν</span>) <span class=\"greek\">σταθήσεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">αὐτοῦ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:18</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:29</a>, 34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:23</a>; 4:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:12</a>; 5:44, 47; 6:52; 9:16; 14:5 (KBeyer, Semitische Syntax im NT, ’62, 94f). <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">κρινεῖ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>; de outro modo (isto é, se fosse injusto) seria impossível a Deus julgar o mundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:6</a>. Cf. 6:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:7</a>, 9, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:17</a>; 4:20 v.l.; B 5:10; MPol 9:3; Hv 3, 9, 10.—Se <span class=\"greek\">πῶς</span> vem acompanhado de uma negação, o ‘impossível’ torna-se com toda a segurança, com toda a certeza (Hyperid. 3, 35; 5, 15; Pr 15:11 <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐχί</span>; EpArist 149; Jos., C. Ap. 1, 256; Just., D. 18, 3 <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐχί</span>; e outros; Tat. 8, 1; 32, 2) <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">χαρίσεται</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:32</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:8</a>.—Como caso excepcional, o opt. com <span class=\"greek\">ἄν</span> (potencial; v. B-D-F §385, 1; Rob. 938; 1021f e Ael. Aristid. 29 p. 557 D.; Just., D. 127, 3; Tat. 16, 1; 17, 3f; Ath. 19, 3 e outros) <span class=\"greek\">πῶς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">δυναίμην</span>;=é-me impossível fazê-lo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:31</a> (v. Gen 44:8; Dt 28:67; Sir 25:3).</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. em perguntas deliberativas com um subjuntivo deliberativo (B-D-F §366, 1; Rob. 934f.—Epict. 4, 1, 100; M. Ant. 9, 40; 2 Km 23:3; Sir 49:11; Ps.-Clem., Hom. 19, 2) <span class=\"greek\">πῶς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">πληρωθῶσιν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">γραφαί</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:54</a>. <span class=\"greek\">πῶς</span> <span class=\"greek\">ὁμοιώσωμεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span>; que comparação podemos encontrar para o Reino? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:30</a>. <span class=\"greek\">πῶς</span> <span class=\"greek\">φύγητε</span>; como escapareis?=de modo algum escapareis <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:33</a>. <span class=\"greek\">πῶς</span> <span class=\"greek\">οὖν</span> com subj. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:14a</a>, seguido de <span class=\"greek\">πῶς</span> <span class=\"greek\">δέ</span> e do subj. três vezes nos vv. 14bc, 15.—Hs 5, 7, 3.</p><p class=\"entry-text\">ⓑ em perguntas indiretas</p><p class=\"entry-text\"><span class=\"greek\">α</span>. com indic. após verbos de saber, dizer, perguntar etc. <span class=\"greek\">ἀκούειν</span> B 7:3 (Just., A I, 40, 1 e outros); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:26</a>. <span class=\"greek\">ἀπαγγέλλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:9</a>. <span class=\"greek\">βλέπειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:15</a>. <span class=\"greek\">διηγεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:27ab</a>; 12:17. <span class=\"greek\">εἰδέναι</span> (X., Mem. 1, 2, 36) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:7</a>; GJs 23:3. <span class=\"greek\">ἐπέχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:7</a>; <span class=\"greek\">ἐπιδεικνύειν</span> B 6:13. <span class=\"greek\">ἐπισκέπτεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:36</a>. <span class=\"greek\">ἐπίστασθαι</span> 20:18. <span class=\"greek\">ἐρωτᾶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:15</a>. <span class=\"greek\">θεωρεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:41</a> (TestAbr B 8 p. 113, 10 [Stone p. 74]). <span class=\"greek\">καταμαθεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a> (sobre <span class=\"greek\">π</span>. <span class=\"greek\">αὐξάνουσιν</span> aqui v. PKatz, JTS 5, ’54; 207–9); ISm 6:2. <span class=\"greek\">κατανοεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:27</a>; 1 Cl 24:1; 37:2. <span class=\"greek\">μεμνῆσθαι</span> GJs 9:2. <span class=\"greek\">μνημονεύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:3</a>. <span class=\"greek\">νοεῖν</span> 1 Cl 19:3. <span class=\"greek\">ὁρᾶν</span> 50:1.—A adição de um artigo confere à pergunta indireta o valor de um substantivo <span class=\"greek\">παρελάβετε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">περιπατεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:1</a> (v. também <span class=\"greek\">β</span> abaixo).—Em algumas das passagens acima apresentadas nesta seção <span class=\"greek\">πῶς</span> poderia ter o mesmo sentido de <span class=\"greek\">ὅτι</span> que, e essa equivalência sugere, ao mesmo tempo, como o falante de grego apreendia o significado de <span class=\"greek\">ὅτι</span> que (sobre a sinonímia no grego posterior v. Epict. 1, 18, 7; 2, 25, 3; 3, 22, 51; Jos., Ant. 12, 205; BGU 37, 6 [50 d.C.]; PRyl 235, 6 <span class=\"greek\">ἐθαύμασα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐδήλωσάς</span> <span class=\"greek\">μοι</span>. V. GHatzidakis, Einl. in die neugriech. Gramm. 1892, 19; Rdm.2 196; B-D-F §396; Rob. 1032). Esse é claramente o sentido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:13</a>; B 11:1; B 14:6; 1 Cl 34:5.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. com subjuntivo deliberativo (ParJer 6, 11 e 14) <span class=\"greek\">μὴ</span> <span class=\"greek\">μεριμνήσητε</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τί</span> <span class=\"greek\">λαλήσητε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:19</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:18</a>; 14:1, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:11</a>. <span class=\"greek\">μεριμνᾷ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">ἀρέσῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:32</a>, 33, 34 (t.r. tem o fut. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:18</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:32–34</a>; v. Herodian 5, 4, 9 <span class=\"greek\">ἠγνόουν</span>, <span class=\"greek\">πῶς</span> <span class=\"greek\">χρήσονται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πράγματι</span>). Também neste caso se pode acrescentar o artigo (v. <span class=\"greek\">α</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:2</a>, 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:21</a> (ParJer 6:15).</p><p class=\"entry-text\">② em exclamações (cf. 1a<span class=\"greek\">β</span>; Schwyzer II 626) como … ! (X., An. 6, 5, 19 e outros; Epict. 1, 16, 13; 4, 1, 115; 116, Ench. 24, 3 <span class=\"greek\">πῶς</span> <span class=\"greek\">ἄνισοί</span> <span class=\"greek\">ἐστε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγνώμονες</span>; M. Ant. 6, 27.—B-D-F §436; Rob. 302; OLagercrantz, Eranos 18, 1918, 26ff; KRupprecht, Philol. 80, 1924, 207) <span class=\"greek\">πῶς</span> <span class=\"greek\">δύσκολόν</span> <span class=\"greek\">ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:24</a>; cf. v. 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:24</a>. <span class=\"greek\">πῶς</span> <span class=\"greek\">συνέχομαι</span> 12:50. <span class=\"greek\">πῶς</span> <span class=\"greek\">ἐφίλει</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:36</a>.—Hm 11:20; 12, 4, 2.—JBauer, Pōs in der gr. Bibel, NovT 2, ’57, 81–91. DELG s.v. <span class=\"greek\">πο</span>-. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώς</h1><div class=\"entry-meta\"><span>partícula enclítica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πώς</span> partícula enclítica (Hom. e outros)</p><p class=\"entry-text\">① como adv.: marcador de meio ou maneira não especificados, de algum modo, de alguma maneira, talvez <span class=\"greek\">ἐάν</span> <span class=\"greek\">πως</span> (cf. SIG 364, 24 [III a.C.]; 3 Km 18:5) ISm 4:1. Com uma negação (Il. 2, 203; 4, 158 e outros; Hdt. 1, 33; Schwyzer II 580) <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ἄν</span> <span class=\"greek\">πως</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">ἐσώθησαν</span> os seres humanos de modo algum poderiam ter sido salvos B 5:10 v.l.—Em combinação com <span class=\"greek\">εἰ</span> v. <span class=\"greek\">εἰ</span> 6n (também Jos., Bell. 6, 422, Ant. 2, 159; M-M s.v. <span class=\"greek\">πως</span>).</p><p class=\"entry-text\">② como conj.: na forma <span class=\"greek\">μή</span> <span class=\"greek\">πως</span> (ou <span class=\"greek\">μήπως</span>; desde Hom., também pap., Sir 28:26; TestSol 6:14 D; TestAbr B 2 p. 106, 8 [Stone p. 60, 8]; TestJob 15:9; TestZeb 4:2; ParJer 5:5), marcador de uma perspectiva negativa que exprime apreensão, frequentemente traduzido por para que não.</p><p class=\"entry-text\">ⓐ em orações que, efetivamente, se caracterizam como orações finais para que … (talvez) não, para que de algum modo não, com subj. aor. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:7</a>; 9:4. GJs 7:1; 8:2.</p><p class=\"entry-text\">ⓑ em orações objetivas, após verbos de apreensão que talvez, por temor de que de algum modo, com subj. aor. após <span class=\"greek\">φοβεῖσθαι</span> (Test. Zeb. 4:2; ParJer 5:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:29</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:3</a>; 12:20a; cf. v. 20b, onde o verbo (<span class=\"greek\">γένωνται</span>) deve ser suprido. Com ind. GJs 14:1; fut. 9:2 fim. Após <span class=\"greek\">βλέπετε</span> cuidai para que … de algum modo não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:9</a> (cf. Sir 28:26). Referindo-se a algo que já aconteceu, com ind. perf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:11</a> (B-D-F §370, 1; Rob. 995; 1169). Elipticamente <span class=\"greek\">μ</span>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">φείσεται</span> (é de temer) que talvez ele também não te poupe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:21</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐπείρασεν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πειράζων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κενὸν</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κόπος</span> <span class=\"greek\">ἡμῶν</span> (com receio) de que o tentador realmente vos tenha tentado (ind., como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:11</a> acima), e então nosso trabalho possa ter sido em vão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5</a>. <span class=\"greek\">μήπως</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πανοῦργος</span> <span class=\"greek\">ἔδωκέν</span> <span class=\"greek\">σοι</span> por temor de que algum mal-intencionado te tenha dado isto GJs 2:3. <span class=\"greek\">μ</span>. <span class=\"greek\">περίγελος</span> tornar-se objeto de escárnio 9:2.</p><p class=\"entry-text\">ⓒ na introdução a uma pergunta indireta (cf. TestJob 15:9) (por temor de que) talvez <span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">κενὸν</span> <span class=\"greek\">τρέχω</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἔδραμον</span> (temendo) que talvez eu esteja correndo ou tenha corrido em vão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:2</a>.—DELG s.v. <span class=\"greek\">πο</span>-. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ρ´</h1><div class=\"entry-meta\"><span>sinal numérico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ρ</span>´ sinal numérico=100 (<span class=\"greek\">ἑκατόν</span>; Jos., C. Ap. 2, 134) Hv 4, 1, 6; GJs 4:3 pap.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥαάβ, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥαάβ</span>, <span class=\"greek\">ἡ</span> indecl. (<span lang=\"he\" dir=\"rtl\">רָחָב</span>; LXX; Just., D. 111, 4.—Em Joseph. <span class=\"greek\">Ῥαάβη</span> [v.l. <span class=\"greek\">Ῥαχάβη</span>], <span class=\"greek\">ης</span> [Ant. 5, 8]) Raabe, uma prostituta em Jericó que, segundo Josh 2, salvou os espias israelitas escondendo-os. Por esta razão foi poupada quando a cidade foi tomada (Josh 6:17, 25). Esta mulher corajosa é citada como modelo de fé, retidão e hospitalidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:25</a>; 1 Cl 12:1, 3. FYoung, JBL 67, ’48, 339–45. V. também <span class=\"greek\">Ῥαχάβ</span> (B-D-F §39, 3; Mlt-H. 109).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαββί</h1><div class=\"entry-meta\"><span>substantivo, forma de tratamento</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥαββί</span> (de <span lang=\"he\" dir=\"rtl\">רַב</span> ‘senhor, mestre’, <span lang=\"he\" dir=\"rtl\">רַבִּי</span> ‘meu senhor’; também <span class=\"greek\">ῥαββεί</span>; sobre a alternância de <span class=\"greek\">ει</span> e <span class=\"greek\">ι</span> v. B-D-F §38; W-S. §5, 13a; v. Mlt-H. 76f.—EbNestle, ZNW 7, 1906, 184) propriamente uma forma de tratamento, e assim em toda a nossa literatura, depois um título honorífico para mestres eminentes da lei: mestre, senhor, rabi <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:7f</a> (também aqui <span class=\"greek\">ῥαββί</span> é uma forma de tratamento). Acerca de João Batista, a quem seus discípulos se dirigiam desta maneira <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:26</a>. De resto, sempre acerca de Jesus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:25</a>, 49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:5</a>; 10:51 v.l.; 11:21; 14:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:49</a>; 4:31; 6:25; 9:2; 11:8. <span class=\"greek\">κύριε</span> <span class=\"greek\">ῥ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:51</a> D; v. o fragmento de evangelho apócrifo ZNW 22, 1923, 153f=PBerlin 11710 (na forma <span class=\"greek\">ῥαμβιού</span> e <span class=\"greek\">ῥαμβίς</span>, v. ASyn. 21, 74; 75; 76). Com a tradução <span class=\"greek\">διδάσκαλε</span>, que parafraseia o sentido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:38</a>; cf. 3:2.—Schürer II 325f; The Jewish Encyclopedia X 1905, 294ff; Dalman, Worte 272–80; TReinach, REJ 48, 1904, 191–96 (ins. de Chipre: <span class=\"greek\">εὐχὴ</span> <span class=\"greek\">ῥαββὶ</span> <span class=\"greek\">Ἀττικοῦ</span>); Billerb. I 916; JNeusner, The Phenomenon of the Rabbi in Later Antiquity, Numen 16, ’69, 1–20; Kl. Pauly IV, 1322f; TRE III, 608; BHHW III 1541ff; ABD V 600–602. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαββουνί</h1><div class=\"entry-meta\"><span>substantivo, forma de tratamento</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥαββουνί</span> (também escrito <span class=\"greek\">ῥαββουνεί</span>, <span class=\"greek\">ῥαββονί</span>, <span class=\"greek\">ῥαββωνί</span>, <span class=\"greek\">ῥαββονεί</span>, v. <span class=\"greek\">ῥαββί</span>), propriamente uma forma intensificada de <span lang=\"he\" dir=\"rtl\">רַב</span>: <span lang=\"he\" dir=\"rtl\">רַבָּן</span> e, ao lado dela, <span lang=\"he\" dir=\"rtl\">רַבּוֹן</span>, com sufixo <span lang=\"he\" dir=\"rtl\">רַבּוֹנִי</span> ou <span lang=\"he\" dir=\"rtl\">רַבּוּנִי</span> meu senhor, meu mestre. Jesus é assim interpelado em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:51</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:16</a>; nesta última passagem acrescenta-se <span class=\"greek\">διδάσκαλε</span> como tradução.—E Kautzsch, Grammatik des Bibl.-Aramäischen 1884, 10; Dalman, Gramm.2 §35, 2, Worte 267; 279, Jesus 12; Schürer II 326; Billerb. II 25; PKahle, The Cairo Geniza ’47, 129 (exemplos de fontes judaicas); WAlbright, Recent Discoveries in Palestine and J, em CHDodd Festschr. ’56, 158 (‘meu querido [ou] pequeno mestre’).—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥαβδίζω</span> (<span class=\"greek\">ῥάβδος</span>; desde Pherecrates Com. [V a.C.] 50; Aristoph.; Theophr.; PRyl 148, 20; LXX) 1 aor. 3 sing. <span class=\"greek\">ἐρράβδισεν</span> Ruth 2:17; pass. <span class=\"greek\">ἐραβδίσθην</span> (sobre a questão de se escrever <span class=\"greek\">ἐρ</span>- ou <span class=\"greek\">ἐρρ</span>- v. B-D-F §11, 1; Mlt. H. 101f; 192f) bater com uma vara, espancar (Aristoph., Lys. 587; Diod S 19, 101, 3), acerca da punição formalmente conhecida na terminologia jurídica latina como admonitio (Dig. Just. 48, 19, 7 ‘veluti fustium’=como no emprego de varas [daí o termo fustigatio para o espancamento propriamente dito]), distinta de catigatio (açoite) e verberatio (flagelação com correntes); Paulo foi espancado três vezes segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:25</a>; em seu caso foi provavelmente a fustigatio prescrita pelos magistrados da cidade, cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:22</a>.—TMommsen, ZNW 2, 1901, p. 89, 1. BAFCS 3, 123–25. DELG s.v. <span class=\"greek\">ῥάβδος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥαβδίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ῥάβδος</span>; Theophr. e outros; Ezk 21:26 v.l.) diminutivo de <span class=\"greek\">ῥάβδος</span>, pedaço de madeira relativamente leve, graveto, raminho Hs 8, 1, 2f; 8, 2, 9.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάβδος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥάβδος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (Hom.+; ins.; PSI 168, 16; PTebt 44, 20; LXX; TestSol 10:4 [personificado]; Test12Patr; JosAs 14:8 [frequentemente cód. A]; ApcEsdr 1:4 p. 24, 10 Tdf.; Philo; Jos., Bell. 2, 365f, Ant. 5, 284; Just.; Mel., P. 13, 85; Ath.) pedaço de madeira relativamente delgado, de comprimento variável, vara, bastão, pau, em geral <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:1</a>; muitas vezes em Hs 8. Acerca da prova que envolve varas (Num 17) 1 Cl 43:2–5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:4</a> (Num 17:23); GJs 9:1. Acerca de um cajado de pastor (Mi 7:14) Hv 5:1; Hs 6, 2, 5; GJs 18:3 v.l. Em linguagem figurada <span class=\"greek\">ποιμαίνειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥ</span>. <span class=\"greek\">σιδηρᾷ</span> (<span class=\"greek\">ποιμαίνω</span> 2a<span class=\"greek\">γ</span> e cf. PGM 36, 109) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:27</a>; 12:5; 19:15. Acerca do bastão de um viajante (literatura s.v. <span class=\"greek\">ὑπόδημα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:3</a>. Acerca do bastão de um governante, cetro (Pind., O. 9, 33 [50]; LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:8</a> (Ps 44:7). Acerca de uma varinha ‘mágica’ (Lucian, Dial. Deor. 7, 4, Dial. Mort. 23, 3; Ps.-Callisth. 1, 1, 3) Hv 3, 2, 4; Hs 9, 6, 3 (Leutzsch, Hermas 409f n. 279). Acerca de uma vara como meio de punição (Pla., Leg. 3, 700c; Plut., Mor. 268d; 693f; Ex 21:20; Is 10:24) <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥάβδῳ</span> <span class=\"greek\">ἔρχεσθαι</span> (oposto a <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span>) vir com uma vara <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:21</a> (v. <span class=\"greek\">ἐν</span> 5a<span class=\"greek\">β</span>). <span class=\"greek\">ῥάβδοι</span> <span class=\"greek\">πυρός</span> varas de fogo APt 19:33. Acerca do bastão de um ancião <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:21</a> (Gen 47:31).—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδοῦχος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥαβδοῦχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ῥάβδος</span>, <span class=\"greek\">ἔχω</span>; Aristoph., Thu. e outros; ins., pap.) originalmente ‘portador de bastão’, depois acerca do ‘litor’ romano (Polyb. e outros; Diod S 5, 40, 1; Plut., Rom. 34 [26, 3], Mor. 280a <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">λικτώρεις</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ῥαβδούχους</span> <span class=\"greek\">ὀνομάζουσι</span>; Herodian 7, 8, 5.—Joseph. não tem a palavra, mas <span class=\"greek\">ῥάβδοι</span> em Bell. 2, 365f provavelmente se refere aos fasces ou feixes de varas levados pelos litores), aproximadamente equivalente a agente da ordem, oficial de polícia. Os <span class=\"greek\">στρατηγοί</span> (v. esse verbete) de Filipos tinham dois litores a seu serviço (JMarquardt, Röm. Staatsverwaltung 12 1881 p. 175, 7; ASherwin-White, Roman Society and Roman Law in the NT ’63, 74f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:35</a>, 38 (Mason 82f [literário]; New Docs 2, 18f).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβιθα.</h1><div class=\"entry-meta\"><span>substantivo feminino, variante textual</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥαβιθα</span>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:41</a> o códice D lê <span class=\"greek\">ραββι</span> <span class=\"greek\">θαβιτα</span>; com isso se quer dizer <span class=\"greek\">ῥαβιθά</span>, o fem. de râbiâ menina; consequentemente <span class=\"greek\">ῥ</span>.=<span class=\"greek\">ταλιθά</span>, que é a leitura da maioria dos testemunhos.—Wlh. ad loc.; FSchulthess, ZNW 21, 1922, 243 nota; TRE III 609.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥαγαύ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥαγαύ</span> (<span lang=\"he\" dir=\"rtl\">רְעוּ</span>), <span class=\"greek\">ὁ</span> indecl. (LXX.—Em Jos., Ant. 1, 148 v.l. <span class=\"greek\">Ῥάγαους</span>) Reú, filho de Pelegue e pai de Serugue (Gen 11:18–21), na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:35</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳδιούργημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥᾳδιούργημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ῥᾳδιουργέω</span> ‘praticar artimanhas’ por intermédio de <span class=\"greek\">ῥᾳδιουργός</span> ‘sem escrúpulos’, que por sua vez deriva de <span class=\"greek\">ῥᾴδιος</span> e de uma raiz verbal associada a <span class=\"greek\">ἔργον</span>; Dionys. Hal. 1, 77; Plut., Pyrrh. 6, 7, Mor. 860d; Ps.-Lucian, Calumn. 20) originalmente a ação de quem procura alcançar algum fim pessoal por meios engenhosos ou ardilosos. Do sentido de ‘travessura, patifaria, artimanha de velhaco, ato astucioso’ é apenas um pequeno passo para o de má ação grave, crime, vilania (Oenomaus em Eus., PE 5, 26, 2) <span class=\"greek\">ῥ</span>. <span class=\"greek\">πονηρόν</span> um ato de grave vilania <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:14</a> (com <span class=\"greek\">ἀδίκημα</span>). DELG s.v. <span class=\"greek\">ῥᾶ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0313-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳδιουργία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥᾳδιουργία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (v. início do verbete anterior; X. e outros; Suda: <span class=\"greek\">ῥ</span>. = <span class=\"greek\">πλατογράφος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κακοῦργος</span> <span class=\"greek\">ἁπλῶς</span> um falsificador e, em geral, uma pessoa má) em seu sentido menos pejorativo <span class=\"greek\">ῥ</span>. sugere uma atitude despreocupada em relação às coisas, em contraste com a aceitação séria das responsabilidades: ‘frivolidade’ (as artimanhas dos escravos são tema comum na comédia greco-romana), depois uma tentativa de alcançar algum fim pessoal por meios engenhosos ou ardilosos, na prática uma expressão atenuada para chicana, maldade, vilania, engano, fraude, falta de escrúpulos (de quem procura uma maneira fácil e duvidosa de fazer as coisas para ganhar dinheiro pode-se dizer, no uso coloquial norte-americano, que procura ‘passar a perna’ nos outros.) (Polyb. 12, 10, 5; Diod S 5, 11, 1; Plut., Cato Min. 16, 3; PMagd 35, 11 [216 a.C.]; BGU 226, 14 [99 d.C.]; POxy 237 VIII, 15; PStras 40, 30; SB 10929 III, 10; Philo, Cher. 80) com <span class=\"greek\">δόλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:10</a>.—AWikenhauser, BZ 8, 1910, 273; CBarrett, em Les Actes des Apôtres, ed. JKremer ’79, 289, acerca de Elimas.—M-M. TW. Spicq.</p></section></article>"};
